const { fonte } = $json;
const pageId = String(fonte?.externalId ?? '');
return [{ json: { inicio: Date.now(), versaoApi: 'v23.0', pageId, pageIdValido: /^\d{5,25}$/.test(pageId) } }];

const contexto = $('Montar requisição').first().json;
const respostaDoToken = $('Token da Página').first().json ?? {};
const tokenDaPagina = typeof respostaDoToken.body?.access_token === 'string' ? respostaDoToken.body.access_token : '';
const paginas = tokenDaPagina
  ? $input.all().map((item) => item.json).filter((json) => json && (json.statusCode !== undefined || json.error))
  : [];
const requests = 1 + paginas.length;
const bytes = paginas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);
const ROTULO_MAXIMO = 200;

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

function semToken(texto) {
  let limpo = String(texto ?? '');
  if (tokenDaPagina) limpo = limpo.split(tokenDaPagina).join('[removido]');
  return limpo.replace(/access_token=[^&\s"']+/g, 'access_token=[removido]').slice(0, 500);
}

function falhaDe(resposta) {
  if (resposta.error) return { causa: 'api_recusou', detalhe: semToken(`falha de rede: ${resposta.error?.message ?? resposta.error}`) };
  if (resposta.statusCode >= 200 && resposta.statusCode < 300) return null;
  const erro = resposta.body?.error;
  const detalhe = semToken(erro?.message || `HTTP ${resposta.statusCode}`);
  const semAcesso = resposta.statusCode === 401 || resposta.statusCode === 403 || [190, 10, 200].includes(erro?.code);
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

if (!contexto.pageIdValido) return devolver([], [{ causa: 'api_recusou', detalhe: 'id da Página inválido' }]);

const falhaDoToken = falhaDe(respostaDoToken);
if (falhaDoToken) return devolver([], [falhaDoToken]);
if (!tokenDaPagina) {
  return devolver([], [{
    causa: 'reauth_pending',
    detalhe: 'A Meta não entregou o token da Página: quem autorizou precisa da tarefa ADVERTISE, MANAGE ou MANAGE_LEADS nela.',
  }]);
}

const recusada = paginas.map(falhaDe).find(Boolean);
if (recusada) return devolver([], [recusada]);

const texto = (valor) => {
  if (typeof valor !== 'string') return null;
  const limpo = valor.trim();
  return limpo ? limpo.slice(0, ROTULO_MAXIMO) : null;
};
const contagem = (valor) => {
  const numero = typeof valor === 'string' && valor.trim() !== '' ? Number(valor) : valor;
  return typeof numero === 'number' && Number.isFinite(numero) && numero >= 0 ? Math.trunc(numero) : null;
};

const porId = new Map();
for (const pagina of paginas) {
  const formularios = Array.isArray(pagina.body?.data) ? pagina.body.data : [];
  for (const formulario of formularios) {
    const formId = typeof formulario?.id === 'string' && /^\d{5,25}$/.test(formulario.id) ? formulario.id : null;
    if (!formId) continue;
    porId.set(formId, {
      formId,
      nome: texto(formulario.name),
      status: typeof formulario.status === 'string' && /^[A-Z_]{1,40}$/.test(formulario.status) ? formulario.status : null,
      leadsTotal: contagem(formulario.leads_count),
      leadsExpirados: contagem(formulario.expired_leads_count),
      criadoEm: typeof formulario.created_time === 'string' && formulario.created_time ? formulario.created_time : null,
    });
  }
}

const linhas = [...porId.values()];
if (linhas.length === 0) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
return devolver(linhas, []);
